import{Ht as e,Rt as t,dt as n,gt as r,mt as i,n as a}from"./chunks/framework.BkIgthgQ.js";var o=JSON.parse(`{"title":"Technical whitepaper","description":"Domain model for default-branch work: object graph, unique owners, leftover 404s. Independently readable.","frontmatter":{"title":"Technical whitepaper","description":"Domain model for default-branch work: object graph, unique owners, leftover 404s. Independently readable."},"headers":[],"relativePath":"en/contribute/whitepaper.md","filePath":"en/contribute/whitepaper.md","lastUpdated":1790057721000}`),s={name:`en/contribute/whitepaper.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="technical-whitepaper" tabindex="-1">Technical whitepaper <a class="header-anchor" href="#technical-whitepaper" aria-label="Permalink to “Technical whitepaper”">​</a></h1><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to “Abstract”">​</a></h2><p>KiriVers is a self-hosted <strong>update catalog and delivery</strong> process: one PostgreSQL catalog, two HTTP planes. The client plane (default <code>:8080</code>) serves native JSON and nine store feeds to software clients. The admin plane (default <code>:8081</code>) hosts the Vue admin SPA and CI. Both client protocols share <code>internal/service/update.SelectTarget</code> as the targeting owner (list feeds project via <code>AnonymousVisible</code>; do not fork).</p><p>The release unit is a <strong>Version</strong> (dual integer and SemVer numbers, changelog, channel, LTS / critical / gray). The downloadable slice is a <strong>Version Line</strong>: that Version on one <code>(os, arch)</code> pair, <strong>with no version number of its own</strong>. Artifact keys are <code>{slug}/{sha256}</code>. Browser uploads keep <code>direct_s3</code> false.</p><p>This page is the <strong>domain model</strong> for default-branch work: object layering, unique implementation owners, leftovers that must stay 404. Operator steps live in the feature guides. Process boot lives in <a href="./architecture">Runtime architecture</a>.</p><h2 id="problem-and-positioning" tabindex="-1">Problem and positioning <a class="header-anchor" href="#problem-and-positioning" aria-label="Permalink to “Problem and positioning”">​</a></h2><p>The problem is shipping <strong>binary installers, firmware images, or multi-file directories</strong> by channel and platform to installed clients, with optional delta or packing — not using git for source collaboration.</p><table tabindex="0"><thead><tr><th>In scope</th><th>Out of scope</th></tr></thead><tbody><tr><td>Self-hosted catalog, native check / download, store feeds, gray allowlist, admin console and CI release</td><td>Git hosting, code review, a CI build farm</td></tr><tr><td>Single-file binary delta; multi-file integrity plus dynamic packing</td><td>Store review queues; distro repositories</td></tr><tr><td>Public-backend artifacts; private-backend GeoIP</td><td>Hosting this documentation site on admin <code>GET /</code></td></tr></tbody></table><p>Not git. Not App Store / Play / Microsoft Store review. Not APT / RPM / Flatpak. Official SDKs wrap native JSON only and do not read feeds.</p><h2 id="runtime-shape" tabindex="-1">Runtime shape <a class="header-anchor" href="#runtime-shape" aria-label="Permalink to “Runtime shape”">​</a></h2><p>One <code>kirivers</code> / <code>kirivers server</code> process, two Gin engines. Boot order: three YAML files → logger → PostgreSQL → storage → cache → dual Gin → job workers (detail: <a href="./architecture">Runtime architecture</a>).</p><table tabindex="0"><thead><tr><th>Plane</th><th>Default addr</th><th>Role</th></tr></thead><tbody><tr><td>Client</td><td><code>:8080</code></td><td><code>POST .../update/check</code>, changelog, pack, store listings, telemetry, announcements</td></tr><tr><td>Admin</td><td><code>:8081</code></td><td>SPA, admin CRUD, CI <code>POST .../ci/releases</code></td></tr></tbody></table><p>When <code>ClientProxyURL</code> is set, the admin plane <strong>reverse-proxies</strong> <code>/api/v1/projects/**</code> to this process’s client listener. Empty <code>ClientProxyURL</code> is tests only: those paths are JSON <code>NOT_FOUND</code> on admin. The Vite dev proxy must list <code>/api/v1/projects</code> <strong>before</strong> <code>/api</code>.</p><p>Admin UI files: Gin <strong>NoRoute</strong> (<code>frontend/embed.go</code> <code>//go:embed all:dist</code>). Never <code>gin.Static</code> / <code>StaticFS</code>. Priority: non-empty <code>static_dir</code> with disk <code>index.html</code> → disk; else embedded FS with <code>index.html</code> → embed; <code>static_dir: &quot;&quot;</code> → UI off.</p><p>The only probe is <code>GET /api/v1/health</code>. JSON <code>ready</code> probes PostgreSQL and object storage, <strong>not</strong> Redis. <code>GET /api/v1/ready</code> is unregistered.</p>`,15),r(d,{code:`flowchart%20TB%0A%20%20subgraph%20proc%20%5Bkirivers%20process%5D%0A%20%20%20%20C%5BGin%20client%20%3A8080%5D%0A%20%20%20%20A%5BGin%20admin%20%3A8081%5D%0A%20%20%20%20S%5Bservice%5D%0A%20%20%20%20C%20--%3E%20S%0A%20%20%20%20A%20--%3E%20S%0A%20%20%20%20A%20--%3E%7Cproxy%20%2Fapi%2Fv1%2Fprojects%7C%20C%0A%20%20end%0A%20%20SPA%5BAdmin%20SPA%20disk%20or%20embed%5D%0A%20%20Vite%5BVite%20%3A3000%5D%0A%20%20Native%5BNative%20SDK%20clients%5D%0A%20%20Feeds%5BStore%20updaters%5D%0A%20%20A%20--%3E%7CNoRoute%20GET%2FHEAD%7C%20SPA%0A%20%20Vite%20--%3E%7C%2Fapi%2Fv1%2Fprojects%20first%7C%20C%0A%20%20Vite%20--%3E%7C%2Fapi%7C%20A%0A%20%20Native%20--%3E%20C%0A%20%20Feeds%20--%3E%20C%0A%20%20SPA%20--%3E%7Cpreview%20via%20proxy%7C%20A%0A`}),o[1]||=i(`<h2 id="object-model" tabindex="-1">Object model <a class="header-anchor" href="#object-model" aria-label="Permalink to “Object model”">​</a></h2><p>Identity: <code>uuid</code>, <code>slug</code>, and unexpired aliases are <code>project_ref</code>. Console <code>name</code> is a Unicode title; it is <strong>not</strong> <code>project_ref</code> and does not appear on client <code>ProjectPublic</code>, check, or feeds.</p><p><code>internal/model</code> layers (not a package tree):</p><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>Project</code></td><td>Catalog root; <code>compare_engine</code>, <code>device_id</code> policy, storage prefix</td></tr><tr><td><code>Channel</code></td><td>Channel slug, <code>stability_rank</code>, unlisted, optional <code>X-Channel-Token</code></td></tr><tr><td>Platform matrix</td><td><code>(os, arch)</code> rows; <code>package_type</code> locks after first publish on that pair</td></tr><tr><td><code>HwRev</code></td><td>Hardware id; feeds and anonymous check use the default variant</td></tr><tr><td><code>Version</code></td><td>Dual numbers, changelog, channel, LTS / critical / gray, <code>min_source_version</code></td></tr><tr><td><code>VersionLine</code></td><td><code>(version, os, arch)</code> slice; <code>min_os</code> / <code>min_api_level</code> live on the line, not matrix columns</td></tr><tr><td><code>Artifact</code></td><td><code>full</code> / <code>store_full</code> / <code>delta</code> / <code>patch</code> / <code>file</code>; key <code>{slug}/{sha256}</code></td></tr></tbody></table><p>Version <strong>owns</strong> changelog, channel, LTS, critical, and gray. A Version Line <strong>has no</strong> version number of its own.</p>`,5),r(d,{code:`flowchart%20TB%0A%20%20P%5BProject%5D%0A%20%20Ch%5BChannel%5D%0A%20%20Mx%5BPlatform%20matrix%5D%0A%20%20Hw%5BHwRev%5D%0A%20%20V%5BVersion%5D%0A%20%20VL%5BVersion%20Line%5D%0A%20%20Art%5BArtifact%5D%0A%20%20P%20--%3E%20Ch%0A%20%20P%20--%3E%20Mx%0A%20%20P%20--%3E%20Hw%0A%20%20P%20--%3E%20V%0A%20%20V%20--%3E%20VL%0A%20%20Mx%20-.-%3E%20VL%0A%20%20VL%20--%3E%20Art%0A`}),o[2]||=i(`<h2 id="version-identity-and-comparison" tabindex="-1">Version identity and comparison <a class="header-anchor" href="#version-identity-and-comparison" aria-label="Permalink to “Version identity and comparison”">​</a></h2><p>Each Version may hold both an integer build and a SemVer. Project <code>compare_engine</code> is <code>integer</code> or <code>semver</code> and decides ordering and targeting; the other number is display and protocol mapping. <code>+build</code> <strong>does not</strong> participate in uniqueness or order. The engine is immutable after the first <strong>published</strong> version (<code>COMPARE_ENGINE_IMMUTABLE</code>).</p><p>Parsing <code>current_version</code> (<code>ParseVersionRef</code>): all digits → integer identity; otherwise SemVer 2.0 with leading <code>v</code> and <code>+build</code> stripped. Unparseable → 400 <code>ENGINE_MISMATCH</code>, <strong>never</strong> treated as <code>0</code>. Parsed but missing from the catalog → 404 <code>VERSION_NOT_FOUND</code>. After locate, comparison uses <strong>only</strong> <code>compare_engine</code>.</p><p>Store adapters map both numbers with a <strong>fixed per-protocol</strong> table (for example Sparkle <code>sparkle:version</code> vs <code>sparkle:shortVersionString</code>), not via a display key or <code>compare_engine</code>. Protocol fields: <a href="./store">Store adapters</a>.</p><p>Admin list-card <code>latest_version</code> uses <code>update.CompareVersions</code> over published + deprecated. It <strong>must not</strong> call <code>SelectTarget</code>.</p><h2 id="two-client-protocols" tabindex="-1">Two client protocols <a class="header-anchor" href="#two-client-protocols" aria-label="Permalink to “Two client protocols”">​</a></h2><ol><li><strong>Native JSON</strong> (the only official SDK path): <code>POST /api/v1/projects/:ref/update/check</code>. Required body: <code>current_version</code>, <code>os</code>, <code>arch</code>. Optional: <code>channel</code>, <code>hw_rev</code>, <code>os_version</code>, <code>device_id</code>, <code>capabilities</code>, <code>accepted_delta_algos</code>. Capabilities: <code>full_package</code> / <code>file_list</code> / <code>patch_package</code> / <code>binary_delta</code>. Undeclared clients advertise <code>full_package</code> only. Leftover query <code>protocol_version</code> is <strong>ignored</strong>; there is no protocol header. <code>GET .../update/check</code> is unregistered (404, no 301).</li><li><strong>Store feeds</strong>: listing-scoped <code>GET .../store/{protocol}/{listing_slug}/{doc}</code>. Nine adapters: <code>sparkle</code>, <code>electron</code>, <code>tauri</code>, <code>squirrel</code>, <code>clickonce</code>, <code>appimage</code>, <code>winget</code>, <code>msix</code>, <code>fdroid</code>. Missing listing slug is <strong>plain-text 404</strong>. SDKs <strong>do not</strong> read feeds. HTTP and enclosure rules: <a href="./store">Store adapters</a>.</li></ol><p>Native check calls <code>SelectTarget</code>. List feeds project the <strong>same anonymous rules</strong> through <code>store.AnonymousVisible</code> (no <code>device_id</code>, default <code>hw_rev</code>, <code>GrayIsComplete</code> only) and must not fork targeting. Single-target dynamic endpoints (Tauri) call <code>SelectTarget</code> directly.</p><p>Check is <strong>not</strong> a CDN object: 200/204 use <code>private, max-age=0, must-revalidate</code> (including anonymous complete gray). <code>cache_s_maxage_seconds</code> does <strong>not</strong> apply to check.</p><div class="danger custom-block"><p class="custom-block-title">Wrong</p><p><code>GET /api/v1/projects/:ref/update/check</code> as the live update-check method.</p></div><div class="tip custom-block"><p class="custom-block-title">Correct</p><p><code>POST /api/v1/projects/:ref/update/check</code>. Leftover GET stays unregistered 404.</p></div><div class="danger custom-block"><p class="custom-block-title">Wrong</p><p><code>GET /api/v1/projects/:ref/store/sparkle/appcast.xml</code> (no listing slug).</p></div><div class="tip custom-block"><p class="custom-block-title">Correct</p><p><code>GET /api/v1/projects/:ref/store/{protocol}/{listing_slug}/{doc}</code>. Missing listing is plain-text 404.</p></div>`,13),r(d,{code:`flowchart%20TB%0A%20%20POST%5BPOST%20%2Fupdate%2Fcheck%20optional%20device_id%5D%0A%20%20LIST%5BGET%20listing%20feed%20anonymous%5D%0A%20%20TAU%5BSingle-target%20feed%20e.g.%20Tauri%5D%0A%20%20ST%5Bupdate.SelectTarget%5D%0A%20%20AV%5Bstore.AnonymousVisible%5D%0A%20%20POST%20--%3E%20ST%0A%20%20TAU%20--%3E%20ST%0A%20%20LIST%20--%3E%20AV%0A%20%20ST%20--%3E%20R200%5B200%20one%20target%5D%0A%20%20ST%20--%3E%20R204%5B204%5D%0A%20%20ST%20--%3E%20R409%5B409%5D%0A%20%20AV%20--%3E%20ITEMS%5Bpublished%20ready%20default-hw%20GrayIsComplete%5D%0A`}),o[3]||=i('<h2 id="target-selection-and-lifecycle" tabindex="-1">Target selection and lifecycle <a class="header-anchor" href="#target-selection-and-lifecycle" aria-label="Permalink to “Target selection and lifecycle”">​</a></h2><p>Version statuses: <code>draft</code> → <code>published</code> → <code>deprecated</code> / <code>revoked</code>. <code>draft</code> is invisible to clients. <code>deprecated</code> is not an automatic upgrade target but remains queryable/downloadable. <code>revoked</code> forbids download and allows a safe downgrade. <code>is_lts</code> may be set later. <code>is_critical</code> publish is <code>GrayIsComplete</code> and cannot enter gray.</p><p>A Version Line enters the catalog only when ready. <code>packs_ready_at</code> is stamped by system <code>auto_delta</code> preheat (channel × <code>delta_source_count</code>). Unstamped → check / feed <code>VERSION_NOT_VISIBLE</code>. Client dynamic pack jobs <strong>must not</strong> write that stamp.</p><p>The <strong>native</strong> target implementation is <code>internal/service/update.SelectTarget</code> (<code>select.go</code>). List feeds project through <code>store.AnonymousVisible</code> (same anonymous filter, not a full <code>SelectTarget</code> run). Announcement matching and admin list-card latest <strong>must not</strong> call <code>SelectTarget</code>.</p><p>Hop: <code>Version.MinSourceVersion</code> only. The winner is the highest compare-key candidate; if current is below that winner’s floor, rewrite along the <code>min_source</code> chain (Published + ready line + hw + channel allowed), max <strong>8</strong> hops. Missing / not-ready / cycle / more than 8 → 409 <code>INTERMEDIATE_UNAVAILABLE</code>. <strong>Do not</strong> skip the blocked newest candidate to pick the next-highest.</p><p>Current line’s own <code>min_os</code> / <code>min_api_level</code> unmet → 409 <code>MIN_OS_NOT_MET</code> (<code>lineMeetsOS</code>, Version Line columns only). Candidate-level failure is a silent skip. A <code>current_version</code> that parses but is not in the catalog → 404 <code>VERSION_NOT_FOUND</code>. Revoked with no safe target → 409 <code>NO_SAFE_TARGET</code>. No update → <strong>204</strong> (still ETag-able).</p><h2 id="channels-tokens-and-gray" tabindex="-1">Channels, tokens, and gray <a class="header-anchor" href="#channels-tokens-and-gray" aria-label="Permalink to “Channels, tokens, and gray”">​</a></h2><p>System <code>stability_rank</code>: alpha 10, beta 20, stable 30. Cross-channel upgrades only move to a stabler (or same-rank, then compare-key) channel. Unlisted: usable when the client’s <strong>current</strong> channel slug or query <code>channel=</code> equals that slug; otherwise skip, do not 404 the whole check.</p><p><code>X-Channel-Token</code> is not project <code>X-Project-Token</code>. Token-protected channel: mismatch makes <code>channelAllowedForUpgrade</code> <strong>skip that channel</strong>; other public channels may still 200; otherwise 204. A wrong token on check is <strong>not</strong> 401/403. Plaintext must not enter ETag, logs, or cache keys. Changelog path mismatch is 404.</p><p>Native gray with <code>device_id</code>: <code>grayHitFor</code> = allowlist until <code>Version.GrayIsComplete()</code> (<code>is_critical</code> or <code>gray_completed_at</code>). Knobs <code>gray_start_percent</code> / <code>gray_step_percent</code> / <code>gray_interval_seconds</code> feed <code>GrayCoverage</code> (desired namebook size) and admission; they <strong>do not</strong> enter <code>grayHitFor</code>. An empty namebook completes immediately. <code>pkg/grayutil</code> is leftover; check <strong>must not</strong> call it. Anonymous clients and feeds see <strong>only</strong> <code>GrayIsComplete</code>; incomplete gray never appears on Sparkle / electron / ….</p><div class="danger custom-block"><p class="custom-block-title">Wrong</p><p>Decide gray hits with an HMAC percent bucket.</p></div><div class="tip custom-block"><p class="custom-block-title">Correct</p><p>With <code>device_id</code>: allowlist until <code>GrayIsComplete</code>. Anonymous / feeds: <code>GrayIsComplete</code> only.</p></div><h2 id="artifacts-and-incremental-updates" tabindex="-1">Artifacts and incremental updates <a class="header-anchor" href="#artifacts-and-incremental-updates" aria-label="Permalink to “Artifacts and incremental updates”">​</a></h2><p>The only download URL builder is <code>update.PackageDownloadURL</code> → <code>/api/v1/projects/{slug}/packages/{64-hex}</code> (single-node or <code>cluster.download=local</code>). With cluster S3-direct the same helper emits the public <code>{slug}/{sha256}</code> object URL. Feed enclosures must use that helper. JSON <code>file_name</code> is an unsigned display name. <code>GET /artifacts/{id}/{filename}</code> is unregistered.</p><p>Single-file <code>binary_delta</code>: three algorithms in <code>internal/delta</code> (bsdiff, xdelta3, hdiffpatch). Server <code>hdiffpatch</code> CGO-links libHDiffPatch and emits uncompressed <code>HDIFF13&amp;</code>; it does not exec a PATH CLI. <code>bsdiff</code> / <code>xdelta3</code> stay pure Go. Magics and dispatch: <a href="./delta">Delta engines</a>. The Go SDK stays <code>CGO_ENABLED=0</code>.</p><p>Multi-file: clients run integrity, then <code>POST /update/pack</code> (enqueue and poll the same URL). Uncompressed Manifest totals over <code>dynamic_pack.max_bytes</code>, or a needed-size ratio that is too large versus the full Manifest → HTTP <strong>200</strong> <code>status=full_package</code>, not 400, and not an admin <code>job_id</code> on the client pack API. Native hash-root zip is <code>kind=full</code>. Store <code>line_full</code> must be <code>kind=store_full</code> (path zip). A multi-file line without <code>store_full</code> is skipped; <strong>never</strong> serve hash-root <code>full</code> as <code>line_full</code>.</p><p>Browser presign keeps <code>direct_s3</code> false; never PUT unknown S3 keys.</p><h2 id="changelog-announcements-and-media" tabindex="-1">Changelog, announcements, and media <a class="header-anchor" href="#changelog-announcements-and-media" aria-label="Permalink to “Changelog, announcements, and media”">​</a></h2><p>Native changelog lives <strong>only</strong> at <code>GET .../changelog/:channel/:os/:arch</code>. Check 200 has <strong>no</strong> <code>changelog</code> / <code>changelog_versions</code>. The check catalog ETag omits Version changelog text. Path channel is required; token mismatch → 404. Markdown <code>${site_url}</code> expands from <strong>RequestOrigin</strong> (ignore Referer).</p><p>Announcements are a separate resource: <code>GET .../announcements</code>, matched only by <code>announcementMatches</code> (seven legal scopes, Version bound by UUID). Empty match is 200 <code>{announcements:[]}</code>, not 204. Do not embed them in check / changelog / feeds, and do not call <code>SelectTarget</code> to match notices. Announcement <code>${site_url}</code> still expands from Referer.</p><p>Media: admin uploads go to <code>storage.Backend</code> (<code>media/…</code>); client GET is UUID-public. Stored Markdown must not embed presigned URLs.</p><div class="danger custom-block"><p class="custom-block-title">Wrong</p><p>Put <code>changelog</code> or <code>changelog_versions</code> on the check 200 body.</p></div><div class="tip custom-block"><p class="custom-block-title">Correct</p><p>Changelog is <code>GET .../changelog/:channel/:os/:arch</code>. Announcements are a dedicated GET.</p></div><h2 id="storage-cdn-and-cluster" tabindex="-1">Storage, CDN, and cluster <a class="header-anchor" href="#storage-cdn-and-cluster" aria-label="Permalink to “Storage, CDN, and cluster”">​</a></h2><p>The process has two object backends:</p><table tabindex="0"><thead><tr><th>Backend</th><th>Keys</th><th>Use</th></tr></thead><tbody><tr><td>Public</td><td><code>{slug}/{sha256}</code></td><td>Installers, deltas, patches, store zips</td></tr><tr><td>Private</td><td><code>geoip/{id}/…</code></td><td>GeoIP MMDB; never Put on the public bucket</td></tr></tbody></table><p>Admin write <strong>locks</strong> project <code>storage_visibility</code> to <code>public</code>; PATCH <code>private</code> → 400. Legacy private rows and local-proxy paths may still exist in code; the console has no “host artifacts privately” switch.</p><p>Check responses must not be treated as public CDN objects (Cache-Control above). <code>ClusterActive</code> = <code>storage.driver=s3</code> <strong>and</strong> <code>cache.driver=redis</code>. Under local-proxy (<code>cluster.download=local</code>), check and feeds use <code>private, no-store</code> so per-node replica visibility does not enter a shared CDN. <code>GET /packages</code> prefers the local replica.</p><p><code>/health</code> <code>ready</code>: DB Ping plus Head of <code>.ready</code> on the public (and, if open, private) backend. Redis runtime failover is not <code>ready=false</code>.</p><h2 id="admin-plane-ci-and-console" tabindex="-1">Admin plane, CI, and console <a class="header-anchor" href="#admin-plane-ci-and-console" aria-label="Permalink to “Admin plane, CI, and console”">​</a></h2><p>Do not mix four credential kinds: instance / platform-admin session (2FA / Passkey), project members, CI token (<code>POST .../ci/releases</code>), project token (client <code>require_client_token</code>). Channel tokens skip a channel; they are not project auth.</p><p>The console is a domain surface, not a second protocol. CRUD uses the admin-plane SDK (<code>@/api/generated</code>). Check / integrity / announcement <strong>preview</strong> uses the client-plane SDK (<code>@/api/generated-client</code>) through the admin listener’s reverse proxy of <code>/api/v1/projects/**</code>. Do not invent a third HTTP client.</p><p>Domain rules:</p><ul><li>Console <code>name</code> is not <code>project_ref</code>.</li><li>Version writes use <code>changelog_i18n</code>; extra locale map keys must not be dropped.</li><li>Gray UI: GET allowlist (<code>client_ids</code>) plus knobs, not a percent-HMAC control.</li><li>Check preview is <strong>POST</strong> <code>checkUpdate</code>. The integrity dialog has no limit control.</li><li><code>direct_s3</code> is always false.</li><li>Platform comboboxes use slug ∪ <code>COMMON_*</code>, never <code>entry.name</code> as stored os/arch.</li></ul><p>Operator steps and the yarn / SFC loop: <a href="./frontend">Admin frontend</a>. Platform-admin surfaces: admins, GeoIP, nodes, security. Project surfaces: overview, settings, channels, matrix, hw-revs, languages, announcements, tokens, release, audit, clients, version + gray.</p><h2 id="auth-signing-and-privacy" tabindex="-1">Auth, signing, and privacy <a class="header-anchor" href="#auth-signing-and-privacy" aria-label="Permalink to “Auth, signing, and privacy”">​</a></h2><p>JSON errors use the <code>pkg/response</code> envelope <code>error.code</code>. Store missing listing is the <strong>exception</strong>: plain-text 404, not that envelope.</p><p>Native response signing (<code>pkg/signature.SignPayload</code>) covers <code>integer</code>, <code>semver</code>, <code>root_hash</code>, <code>package_url</code>, <code>size</code>, <code>sha256</code> fields — not file bytes. Sparkle <code>edSignature</code> is Ed25519 over enclosure <strong>file bytes</strong>, a different signature from the native payload.</p><p><code>device_id</code> policies: <code>hashed</code> (default; stored digest from project <code>DeviceSecret</code>), <code>raw</code> (discouraged), <code>none</code> (do not insert a <code>clients</code> row — same as missing <code>device_id</code>; an empty namebook completes gray). The digest key never appears in API JSON. Application logs write Fingerprint only, never raw <code>device_id</code>.</p><p>Presence is <code>POST .../clients/report</code> → <code>{ip, country_code, region_code, geo_i18n}</code>. Leftover <code>POST .../clients/login</code> stays 404. Report with <code>device_id_policy=none</code> is 400.</p><h2 id="official-sdk-boundary" tabindex="-1">Official SDK boundary <a class="header-anchor" href="#official-sdk-boundary" aria-label="Permalink to “Official SDK boundary”">​</a></h2><p>Each language lives on an orphan branch <code>sdk/&lt;lang&gt;</code> in a <strong>separate git worktree</strong>. Go / PHP / Swift <code>sdk/go</code> (and siblings) are pointer READMEs; full sources live on <code>sdk/go-src</code> / <code>sdk/php-src</code> / <code>sdk/swift-src</code> and then dedicated publish remotes. The default branch has <strong>no</strong> <code>sdk/</code> tree and must not merge any <code>sdk/*</code>.</p><p>SDKs wrap native JSON only. Language agents <strong>must not</strong> edit the default-branch tree (including <code>internal/</code>); if the server is wrong they write <code>BACKEND_ISSUE.md</code> in the language worktree. Install coordinates: <a href="/en/api/sdk/">API → SDK</a>. Maintainer branch rules: <a href="./sdk">SDK source branches</a>.</p><h2 id="out-of-scope-and-leftovers-that-must-stay-unregistered" tabindex="-1">Out of scope and leftovers that must stay unregistered <a class="header-anchor" href="#out-of-scope-and-leftovers-that-must-stay-unregistered" aria-label="Permalink to “Out of scope and leftovers that must stay unregistered”">​</a></h2><p>The product does not replace git, closed-store review, APT/RPM/Flatpak, a second updater binary, hosting this docs site on admin <code>GET /</code>, or unpublished in-process CGO delta.</p><p>Unique owners (do not fork):</p><table tabindex="0"><thead><tr><th>Invariant</th><th>Unique owner</th><th>Must not</th></tr></thead><tbody><tr><td>Native target</td><td><code>update.SelectTarget</code></td><td>Forking list-feed filters; announcement matching; list-card latest</td></tr><tr><td>List-feed projection</td><td><code>store.AnonymousVisible</code></td><td>Adapter-local visibility; using full <code>SelectTarget</code> as a list</td></tr><tr><td>List-card latest</td><td><code>update.CompareVersions</code> (published+deprecated)</td><td><code>SelectTarget</code></td></tr><tr><td>Native gray hit</td><td>Allowlist until <code>Version.GrayIsComplete</code></td><td><code>pkg/grayutil</code>, HMAC, <code>rollout_percent</code></td></tr><tr><td>Channel token on check</td><td>Skip channel, never 401/403</td><td>Treating wrong <code>X-Channel-Token</code> as auth failure</td></tr><tr><td>Announcement match</td><td><code>announcementMatches</code></td><td>Embedding in check; calling <code>SelectTarget</code></td></tr><tr><td>Native changelog</td><td><code>GET .../changelog/:channel/:os/:arch</code></td><td>Check 200 <code>changelog*</code></td></tr><tr><td>Artifact HTTP URL</td><td><code>update.PackageDownloadURL</code></td><td><code>/artifacts/{id}/{filename}</code>; unknown-key PresignPut</td></tr><tr><td>Feed enclosure</td><td>Same helper as check</td><td>Adapter-local URL builders</td></tr><tr><td>Store <code>line_full</code></td><td><code>kind=store_full</code></td><td>Hash-root <code>kind=full</code></td></tr><tr><td>Native pack oversize</td><td>200 <code>status=full_package</code></td><td>400; exposing admin <code>job_id</code> on client pack</td></tr><tr><td>JSON errors</td><td><code>pkg/response</code></td><td>Store missing listing (plain-text 404)</td></tr><tr><td>Admin UI files</td><td>NoRoute; <code>frontend/embed.go</code></td><td><code>gin.Static</code> / <code>StaticFS</code></td></tr><tr><td>OpenAPI</td><td><code>openapi.admin.json</code> / <code>openapi.client.json</code></td><td>Hand-editing <code>generated*</code></td></tr><tr><td>SPA client-plane preview</td><td><code>@/api/generated-client</code> + <code>/api/v1/projects/**</code> proxy</td><td>A third HTTP client</td></tr></tbody></table><p>Leftover HTTP that must stay unregistered (404, no 301):</p><table tabindex="0"><thead><tr><th>Path</th><th>Live replacement</th></tr></thead><tbody><tr><td><code>GET .../update/check</code></td><td><code>POST .../update/check</code></td></tr><tr><td><code>POST .../clients/login</code></td><td><code>POST .../clients/report</code> (geo four fields only)</td></tr><tr><td><code>/store/{protocol}/{doc}</code> (no listing slug)</td><td><code>/store/{protocol}/{listing_slug}/{doc}</code></td></tr><tr><td><code>GET /api/v1/ready</code></td><td><code>GET /api/v1/health</code> (<code>ready</code> inside JSON, excludes Redis)</td></tr></tbody></table><p>Leftover query <code>protocol_version</code> on POST check is ignored; do not revive it as a negotiation header.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further reading”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Content</th></tr></thead><tbody><tr><td><a href="./architecture">Runtime architecture</a></td><td>Boot chain, NoRoute, <code>/api/v1/projects</code> proxy, probes</td></tr><tr><td><a href="./backend">Backend layering</a></td><td>controller / service / repository</td></tr><tr><td><a href="./frontend">Admin frontend</a></td><td>Dual SDK, Vite proxy, yarn loop</td></tr><tr><td><a href="./delta">Delta engines</a></td><td>Three algorithms and magics</td></tr><tr><td><a href="./store">Store adapters</a></td><td>Nine-protocol HTTP and enclosures</td></tr><tr><td><a href="./openapi">OpenAPI contract</a></td><td>Two plane JSON files</td></tr><tr><td><a href="./sdk">SDK source branches</a></td><td><code>sdk/&lt;lang&gt;</code> worktrees</td></tr><tr><td>Feature guides</td><td><a href="/en/guide/features/channels">Channels</a>, <a href="/en/guide/features/gray">Gray</a>, <a href="/en/guide/features/incremental">Incremental</a> and other operator steps</td></tr><tr><td><a href="/en/api/sdk/">API → SDK</a></td><td>Language install</td></tr><tr><td>Repo <code>.trellis/spec/</code></td><td>Contributor executable contracts (not an install guide)</td></tr></tbody></table>',52)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};